<script setup lang="ts">
import { ref,onMounted,onUnmounted } from 'vue'
import { api,post } from '../api'
const certificateName=ref(''),certificates=ref<any[]>([])
const domain=ref(''),port=ref(443),certificate=ref(''),privateKey=ref(''),password=ref(''),code=ref(''),state=ref<any>({}),error=ref(''),busy=ref(false),now=ref(Date.now())
let timer:ReturnType<typeof setInterval>|undefined
async function refresh(){try{state.value=await api('gateway');certificates.value=await api('certificates');if(!domain.value){domain.value=state.value.domain||'';port.value=state.value.port||443;certificateName.value=state.value.certificateName||''}}catch(e){error.value=String(e)}}
async function apply(){if(!confirm('修改面板入口可能中断连接。请在新地址登录并于 60 秒内确认，否则恢复旧配置。'))return;busy.value=true;error.value='';try{state.value=await post('gateway',{Action:'apply',Domain:domain.value,Port:port.value,CertificateName:certificateName.value,Certificate:certificate.value,PrivateKey:privateKey.value,Password:password.value,Code:code.value,Confirm:true});certificate.value='';privateKey.value='';password.value='';code.value=''}catch(e){error.value=String(e)}finally{busy.value=false}}
async function confirmAccess(){if(location.hostname!==state.value.domain||Number(location.port||443)!==state.value.port||location.protocol!=='https:'){error.value='请通过新 HTTPS 地址登录后在此确认连接。';return};busy.value=true;try{state.value=await post('gateway',{Action:'confirm'})}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(()=>{refresh();timer=setInterval(()=>{now.value=Date.now();if(state.value.pendingUntil&&now.value>state.value.pendingUntil*1000)refresh()},1000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="card"><h2>面板访问入口</h2><div class="notice">后端固定监听本机 9090，通过 Nginx 配置对外 HTTPS。证书必须覆盖访问域名；修改前请放行新端口。保存后 60 秒未确认会恢复上一配置。</div><p v-if="error" class="error">{{error}}</p><div v-if="state.pendingUntil" class="notice"><strong>等待新入口确认 · 剩余 {{Math.max(0,Math.ceil(state.pendingUntil-now/1000))}} 秒</strong><p><a :href="`https://${state.domain}:${state.port}/#settings`" target="_blank" rel="noreferrer">打开新入口 https://{{state.domain}}:{{state.port}}</a></p><button class="primary" :disabled="busy" @click="confirmAccess">确认新入口连接正常</button></div><form class="form-grid" @submit.prevent="apply"><label>访问域名<input v-model="domain" required placeholder="panel.example.com"></label><label>HTTPS 端口<input v-model.number="port" type="number" min="1" max="65535" required></label><label>使用受管证书（自动续期同步生效）<select v-model="certificateName"><option value="">手动提供证书</option><option v-for="c in certificates" :key="c.name" :value="c.name">{{c.name}} · {{c.domains.join(', ')}}</option></select></label><label>PEM 证书链<textarea v-model="certificate" rows="4" placeholder="首次必须提供，后续留空使用现有证书"></textarea></label><label>PEM 私钥<textarea v-model="privateKey" rows="4" placeholder="不提供下载；保存后清空"></textarea></label><label>管理员密码<input v-model="password" type="password" autocomplete="current-password" required></label><label>双因素验证码（已启用时填写）<input v-model="code" inputmode="numeric" maxlength="6"></label><div class="form-actions"><button class="primary" :disabled="busy||!!state.pendingUntil">{{busy?'应用中…':'校验并修改入口'}}</button><button type="button" @click="refresh">刷新状态</button></div></form></section></template>
